<script setup lang="ts">
import {computed,ref} from 'vue';import {IconDeviceFloppy,IconRefresh,IconChevronRight,IconRotate,IconAdjustmentsHorizontal} from '@tabler/icons-vue';import Rect from './Rect.vue';import Art from './Art.vue';import {draft,referenceMode,show,saveParameters,latestComposition} from './state';import SealViewer from '../components/SealViewer.vue';import {current} from '../store'
const step=ref(0),inkTab=ref('传统印泥'),paper=ref('宣纸'),layout=ref('单字'),alignment=ref('居中'),edge=ref(2),stone=ref(1),gold=ref(1),base=ref(1),depth=ref(70),round=ref(55),weather=ref(40),edgeDetail=ref(60),edgeDepth=ref(50),goldCoverage=ref(65),goldShine=ref(80)
if(!draft.value.text)draft.value.text='印脉重生'
const text=computed({get:()=>draft.value.text,set:v=>draft.value.text=v})
const mesh=computed(()=>current.value?.artifacts.filter(a=>a.kind==='stl').at(-1))
const names=['青田石','寿山石','鸡血石','昌化石','田黄石','巴林石','松花石','灵璧石']
