</script>
<template>
<Rect :x="170" :y="0" :w="1502" :h="592" plain><Art name="customize-scene" class="im-desktop-only" alt="个性定制，工坊与印章视觉参考背景"/><Art name="customize-mobile-title" class="im-mobile-only" alt="个性定制"/></Rect>
<Rect :x="582" :y="65" :w="1074" :h="51" title="定制步骤"><div class="im-custom-steps"><button v-for="(s,i) in ['印面设计','材质工艺','印泥效果','装裱展示']" :class="{active:step===i}" @click="step=i"><b>{{i+1}}</b>{{s}} <IconChevronRight :size="13"/></button><button class="im-gold-button" @click="saveParameters({step,inkTab,paper,layout,alignment,edge,stone,gold,base,depth,round,weather,edgeDetail,edgeDepth,goldCoverage,goldShine})"><IconDeviceFloppy :size="19"/> 保存方案</button></div></Rect>
<Rect :x="268" :y="177" :w="211" :h="332" title="调整前"><div class="im-before"><h2>调整前</h2><Art name="customize-before" alt="初稿概念参考"/><span>{{referenceMode?'AI生成初稿':'视觉初稿参考'}}</span></div></Rect>
<Rect :x="478" :y="123" :w="655" :h="430" plain><SealViewer v-if="!referenceMode&&latestComposition&&mesh" :url="mesh.url"/><template v-else><Art name="customize-main-art" class="im-desktop-only" alt="调整后印章视觉概念，非真实制造结果"/><Art name="customize-mobile-main" class="im-mobile-only" alt="狮钮视觉参考"/></template></Rect>
<Rect :x="951" :y="177" :w="173" :h="305" title="调整后"><div class="im-after"><h2>调整后</h2><p>{{referenceMode?'精修定制效果':'概念效果参考'}}</p><span>方寸藏山河<br>一印定乾坤</span></div></Rect>
<Rect :x="1166" :y="141" :w="490" :h="345" title="印泥预览"><div class="im-ink-preview"><h2>印泥预览</h2><img v-if="!referenceMode&&latestComposition" :src="latestComposition.preview_url||latestComposition.seal.original_url" alt="实际规范字排版预览"><Art v-else name="customize-impression" alt="印脉重生印泥参考效果"/><div class="im-ink-options"><div class="im-segmented"><button v-for="t in ['传统印泥','个性调色']" :class="{active:inkTab===t}" @click="inkTab=t">{{t}}</button></div><div v-if="inkTab==='传统印泥'" class="im-ink-swatches"><button v-for="(s,i) in inks" :class="{selected:draft.ink===colors[i]}" @click="draft.ink=colors[i]!"><Art :name="'ink-'+i" :alt="s+'印泥色泽'"/><span>{{s}}</span></button></div><label v-else class="im-custom-color">选择印泥色<input type="color" v-model="draft.ink" aria-label="印泥自定义颜色"></label></div><div class="im-paper"><span>纸张效果</span><button v-for="p in ['宣纸','绢帛','笺笺','拓片']" :class="{active:paper===p}" @click="paper=p">{{p}}</button></div></div></Rect>
<Rect :x="691" :y="548" :w="381" :h="37" plain><button class="im-rotation-hint" @click="show('mesh','真实三维印面',{url:mesh?.url})"><IconRotate :size="20"/> 拖动旋转 / 滚轮缩放 / 点击查看细节</button></Rect>
<Rect :x="181" :y="598" :w="288" :h="309" title="印面布局"><div class="im-custom-panel"><h2>印面布局</h2><div class="im-chip-row"><button v-for="s in ['单字','双字','多字','自定义']" :class="{selected:layout===s}" @click="layout=s">{{s}}</button></div><div class="im-layout-samples"><button v-for="i in 4" :class="{selected:i===3}" @click="draft.layout=['square','vertical','horizontal','square'][i-1]!;"><Art :name="'layout-'+(i-1)" alt="排版形式参考"/></button></div><label>印文内容<input v-model="text" maxlength="12" aria-label="定制印文内容"><small>{{text.length}}/12</small></label><span>排版方式</span><div class="im-chip-row im-alignments"><button v-for="a in ['居中','对齐','疏离','平衡']" :class="{selected:alignment===a}" @click="alignment=a;draft.layout=a==='对齐'?'vertical':'square'"><IconAdjustmentsHorizontal :size="22"/><span>{{a}}</span></button></div></div></Rect>
<Rect :x="472" :y="598" :w="230" :h="309" title="刀痕深浅"><div class="im-custom-panel"><h2>刀痕深浅</h2><button class="im-depth-art" @click="show('image','刀痕深浅参考',{image:'/assets/museum/customize-depth.png'})"><Art name="customize-depth" alt="印面浮雕刀痕视觉参考"/></button><label class="im-slider">刀痕深度<input type="range" min="0" max="100" v-model="depth" aria-label="刀痕深度"><span>{{depth}}%</span></label><label class="im-slider">刀口圆融<input type="range" min="0" max="100" v-model="round" aria-label="刀口圆融"><span>{{round}}%</span></label><label class="im-slider">边缘风化<input type="range" min="0" max="100" v-model="weather" aria-label="边缘风化"><span>{{weather}}%</span></label></div></Rect>
<Rect :x="706" :y="598" :w="337" :h="309" title="边饰纹样"><div class="im-custom-panel"><h2>边饰纹样</h2><div class="im-chip-row"><button v-for="(s,i) in ['无边饰','回纹','云纹','蟠龙','山水','自定义']" :class="{selected:edge===i}" @click="edge=i">{{s}}</button></div><div class="im-edge-samples"><button v-for="i in 10" :class="{selected:i===edge+1}" @click="edge=(i-1)%6"><Art :name="'edge-'+(i-1)" alt="边饰纹样参考"/></button></div><label class="im-slider">纹样粗细<input type="range" v-model="edgeDetail" aria-label="纹样粗细"><span>{{edgeDetail}}%</span></label><label class="im-slider">纹样密度<input type="range" v-model="edgeDepth" aria-label="纹样密度"><span>{{edgeDepth}}%</span></label></div></Rect>
<Rect :x="1047" :y="598" :w="323" :h="309" title="材质选择"><div class="im-custom-panel"><h2>材质选择</h2><div class="im-chip-row"><button v-for="s in ['印石','玉石','金属','其他']" :class="{selected:draft.material===s||s==='印石'&&!['玉石','金属','其他'].includes(draft.material)}" @click="draft.material=s">{{s}}</button></div><div class="im-stone-samples"><button v-for="(s,i) in names" :class="{selected:stone===i}" @click="stone=i;draft.material=s"><Art :name="'stone-'+i" :alt="s+'石材参考'"/><span>{{s}}</span></button></div></div></Rect>
<Rect :x="1375" :y="598" :w="281" :h="185" title="鎏金工艺"><div class="im-custom-panel"><h2>鎏金工艺</h2><div class="im-gold-samples"><button v-for="(s,i) in ['无鎏金','局部鎏金','全鎏金']" :class="{selected:gold===i}" @click="gold=i"><Art :name="'gold-'+i" :alt="s+'效果示例'"/><span>{{s}}</span></button></div><label class="im-slider">鎏金范围<input type="range" v-model="goldCoverage" aria-label="鎏金范围"><span>{{goldCoverage}}%</span></label><label class="im-slider">鎏金亮度<input type="range" v-model="goldShine" aria-label="鎏金亮度"><span>{{goldShine}}%</span></label></div></Rect>
<Rect :x="1375" :y="790" :w="281" :h="117" title="装裱展示"><div class="im-custom-panel"><h2>装裱展示 </h2><div class="im-base-samples"><button v-for="(s,i) in ['无印座','黑檀木座','红木座','玉石座','铜印座']" :class="{selected:base===i}" @click="base=i"><Art :name="'base-'+i" :alt="s+'展示参考'"/><span>{{s}}</span></button></div></div></Rect>
</template>
